/* ============================================================================
 * app/startup/crt0.S  --  fixed preamble for the Hiworld canbox APP
 * Nations N32L406CBL7 (Cortex-M4F, Thumb-2).
 *
 * GENERATED by scratch gen_crt0.py from three pieces of hard evidence:
 *   reference/bootloader_0x08000000_8k.bin    immutable vector table -> slot map
 *   reference/2429-H1N4JPF20A-220524.app.bin  stock veneer targets + trap codes
 *   Nations N32L40x_Library 2.3.0 n32l40x.h   official IRQn_Type names
 *
 * This file owns flash 0x08002000..0x08002209 and MUST keep that exact layout:
 *
 *   0x08002000..0x08002029   42 bytes, NOT dispatched to -> safe filler
 *   0x0800202a..0x08002201   59 x 8-byte veneers (push {r4,lr}; bl h; pop {r4,pc})
 *   0x08002202..0x08002209   app entry veneer  <-- bootloader does `bl 0x08002202`
 *
 * WHY THE VENEER ADDRESSES ARE LOAD-BEARING
 * The app has NO vector table. It runs on the bootloader's (VTOR = 0x08000000,
 * MSP = 0x20000600). That table lives in write-protected flash and branches
 * straight to these addresses, so a veneer SLOT may never move; only its `bl`
 * target may change.
 *
 * THE SLOT MAP IS NOT LINEAR  (corrects docs/hiworld-startup-sequence.md §2)
 * The quoted rule `veneer(IRQn) = 0x08002072 + 8*IRQn` holds only for IRQ0..10
 * and IRQ23..41. The reason is now clear: the app's veneer array is laid out in
 * *STM32F103* vector order (this firmware is an F103 port), while the chip is a
 * Nations N32L406 with different interrupt numbers. The bootloader's table is
 * what bridges the two, e.g. for the CAN block:
 *
 *     N32 CAN_TX  = IRQ53 -> slot 28   (F103 CAN1_TX  = IRQ19)
 *     N32 CAN_RX0 = IRQ54 -> slot 29   (F103 CAN1_RX0 = IRQ20)
 *     N32 CAN_RX1 = IRQ55 -> slot 30   (F103 CAN1_RX1 = IRQ21)
 *     N32 CAN_SCE = IRQ56 -> slot 31   (F103 CAN1_SCE = IRQ22)
 *     N32 ADC     = IRQ19 -> slot 27   (F103 ADC1_2   = IRQ18)
 *
 * Consequence: `can_init`'s NVIC_Init(IRQn = 0x36 = 54) is CORRECT, and the
 * "CAN RX0 anomaly" in the docs does not exist. CAN_RX0_IRQn really is 54 on
 * this part (confirmed in the vendor header), and the bootloader routes IRQ54
 * to slot 29 -- exactly where the stock CAN RX handler sits. Do not "fix" it.
 *
 * Slots the bootloader never dispatches to are unreachable by hardware and are
 * kept only as padding so the reachable slots stay at their addresses.
 *
 * Handlers are .weak: porting a subsystem overrides the default, which
 * otherwise reproduces the stock fatal_error_reset(<original code>).
 * ==========================================================================*/

    .syntax unified
    .cpu    cortex-m4
    .thumb

    .section .image_entry, "ax", %progbits
    .align  1

/* ---- 0x08002000: 42 bytes, unreachable --------------------------------------
 * Stock has ARM C-library __rt_stackheap_init fragments here, reached only from
 * its own __main. Nothing branches here from outside, so fill with `b .` to
 * park a stray branch instead of letting it run on into the veneer array. */
_preamble_filler:
    .rept   21
    b       .
    .endr
    .org    0x2a, 0x00          /* veneer array must start at 0x0800202a */

/* ---- 0x0800202a: the 59 veneers ------------------------------------------ */
    .macro  VENEER  handler
    push    {r4, lr}
    bl      \handler
    pop     {r4, pc}
    .endm

    /* slot 0  0x0800202a  NMI            stock: fatal_error_reset(100) */
    VENEER  NMI_Handler
    /* slot 1  0x08002032  HardFault      stock: fatal_error_reset(101) */
    VENEER  HardFault_Handler
    /* slot 2  0x0800203a  MemManage      stock: fatal_error_reset(102) */
    VENEER  MemManage_Handler
    /* slot 3  0x08002042  BusFault       stock: fatal_error_reset(103) */
    VENEER  BusFault_Handler
    /* slot 4  0x0800204a  UsageFault     stock: fatal_error_reset(104) */
    VENEER  UsageFault_Handler
    /* slot 5  0x08002052  --             stock: fatal_error_reset(110) */
    VENEER  Slot5_Unused_Handler
    /* slot 6  0x0800205a  DebugMon       stock: fatal_error_reset(111) */
    VENEER  DebugMon_Handler
    /* slot 7  0x08002062  --             stock: fatal_error_reset(112) */
    VENEER  Slot7_Unused_Handler
    /* slot 8  0x0800206a  --             stock: fatal_error_reset(113) */
    VENEER  Slot8_Unused_Handler
    /* slot 9  0x08002072  WWDG           stock: fatal_error_reset(114) */
    VENEER  WWDG_IRQHandler
    /* slot 10 0x0800207a  PVD            stock: fatal_error_reset(115) */
    VENEER  PVD_IRQHandler
    /* slot 11 0x08002082  TAMPER         stock: fatal_error_reset(116) */
    VENEER  TAMPER_IRQHandler
    /* slot 12 0x0800208a  RTC            stock: fatal_error_reset(117) */
    VENEER  RTC_IRQHandler
    /* slot 13 0x08002092  FLASH          stock: fatal_error_reset(118) */
    VENEER  FLASH_IRQHandler
    /* slot 14 0x0800209a  RCC            stock: fatal_error_reset(119) */
    VENEER  RCC_IRQHandler
    /* slot 15 0x080020a2  EXTI0          stock: fatal_error_reset(120) */
    VENEER  EXTI0_IRQHandler
    /* slot 16 0x080020aa  EXTI1          stock: fatal_error_reset(121) */
    VENEER  EXTI1_IRQHandler
    /* slot 17 0x080020b2  EXTI2          STOCK HANDLER @0x08002edc */
    VENEER  EXTI2_IRQHandler
    /* slot 18 0x080020ba  EXTI3          stock: fatal_error_reset(123) */
    VENEER  EXTI3_IRQHandler
    /* slot 19 0x080020c2  EXTI4          stock: fatal_error_reset(124) */
    VENEER  EXTI4_IRQHandler
    /* slot 20 0x080020ca  --             stock: fatal_error_reset(125) */
    VENEER  Slot20_Unused_Handler
    /* slot 21 0x080020d2  --             stock: fatal_error_reset(126) */
    VENEER  Slot21_Unused_Handler
    /* slot 22 0x080020da  --             stock: fatal_error_reset(127) */
    VENEER  Slot22_Unused_Handler
    /* slot 23 0x080020e2  --             stock: fatal_error_reset(128) */
    VENEER  Slot23_Unused_Handler
    /* slot 24 0x080020ea  --             stock: fatal_error_reset(129) */
    VENEER  Slot24_Unused_Handler
    /* slot 25 0x080020f2  --             stock: fatal_error_reset(130) */
    VENEER  Slot25_Unused_Handler
    /* slot 26 0x080020fa  --             stock: fatal_error_reset(131) */
    VENEER  Slot26_Unused_Handler
    /* slot 27 0x08002102  ADC            stock: fatal_error_reset(132) */
    VENEER  ADC_IRQHandler
    /* slot 28 0x0800210a  CAN_TX         stock: empty stub (bx lr) */
    VENEER  CAN_TX_IRQHandler
    /* slot 29 0x08002112  CAN_RX0        STOCK HANDLER @0x08002f32 */
    VENEER  CAN_RX0_IRQHandler
    /* slot 30 0x0800211a  CAN_RX1        stock: empty stub (bx lr) */
    VENEER  CAN_RX1_IRQHandler
    /* slot 31 0x08002122  CAN_SCE        stock: empty stub (bx lr) */
    VENEER  CAN_SCE_IRQHandler
    /* slot 32 0x0800212a  EXTI9_5        STOCK HANDLER @0x08002f3e */
    VENEER  EXTI9_5_IRQHandler
    /* slot 33 0x08002132  TIM1_BRK       stock: fatal_error_reset(134) */
    VENEER  TIM1_BRK_IRQHandler
    /* slot 34 0x0800213a  TIM1_UP        stock: fatal_error_reset(135) */
    VENEER  TIM1_UP_IRQHandler
    /* slot 35 0x08002142  TIM1_TRG_COM   stock: fatal_error_reset(136) */
    VENEER  TIM1_TRG_COM_IRQHandler
    /* slot 36 0x0800214a  TIM1_CC        stock: fatal_error_reset(137) */
    VENEER  TIM1_CC_IRQHandler
    /* slot 37 0x08002152  TIM2           STOCK HANDLER @0x08002f72 */
    VENEER  TIM2_IRQHandler
    /* slot 38 0x0800215a  TIM3           stock: fatal_error_reset(138) */
    VENEER  TIM3_IRQHandler
    /* slot 39 0x08002162  TIM4           stock: fatal_error_reset(139) */
    VENEER  TIM4_IRQHandler
    /* slot 40 0x0800216a  I2C1_EV        stock: fatal_error_reset(140) */
    VENEER  I2C1_EV_IRQHandler
    /* slot 41 0x08002172  I2C1_ER        stock: fatal_error_reset(141) */
    VENEER  I2C1_ER_IRQHandler
    /* slot 42 0x0800217a  I2C2_EV        stock: fatal_error_reset(142) */
    VENEER  I2C2_EV_IRQHandler
    /* slot 43 0x08002182  I2C2_ER        stock: fatal_error_reset(143) */
    VENEER  I2C2_ER_IRQHandler
    /* slot 44 0x0800218a  SPI1           stock: fatal_error_reset(144) */
    VENEER  SPI1_IRQHandler
    /* slot 45 0x08002192  SPI2           stock: fatal_error_reset(145) */
    VENEER  SPI2_IRQHandler
    /* slot 46 0x0800219a  USART1         stock: empty stub (bx lr) */
    VENEER  USART1_IRQHandler
    /* slot 47 0x080021a2  USART2         STOCK HANDLER @0x08003016 */
    VENEER  USART2_IRQHandler
    /* slot 48 0x080021aa  USART3         stock: empty stub (bx lr) */
    VENEER  USART3_IRQHandler
    /* slot 49 0x080021b2  EXTI15_10      stock: fatal_error_reset(148) */
    VENEER  EXTI15_10_IRQHandler
    /* slot 50 0x080021ba  RTCAlarm       stock: fatal_error_reset(149) */
    VENEER  RTCAlarm_IRQHandler
    /* slot 51 0x080021c2  --             stock: fatal_error_reset(150) */
    VENEER  Slot51_Unused_Handler
    /* slot 52 0x080021ca  TIM5           stock: fatal_error_reset(151) */
    VENEER  TIM5_IRQHandler
    /* slot 53 0x080021d2  --             stock: fatal_error_reset(152) */
    VENEER  Slot53_Unused_Handler
    /* slot 54 0x080021da  UART4          stock: fatal_error_reset(153) */
    VENEER  UART4_IRQHandler
    /* slot 55 0x080021e2  UART5          stock: fatal_error_reset(154) */
    VENEER  UART5_IRQHandler
    /* slot 56 0x080021ea  TIM6           stock: fatal_error_reset(155) */
    VENEER  TIM6_IRQHandler
    /* slot 57 0x080021f2  TIM7           stock: fatal_error_reset(156) */
    VENEER  TIM7_IRQHandler
    /* slot 58 0x080021fa  --             stock: fatal_error_reset(164) */
    VENEER  Slot58_Unused_Handler

    .org    0x202, 0x00         /* HARD REQUIREMENT: entry veneer at 0x08002202 */

/* ---- 0x08002202: app entry ------------------------------------------------
 * The bootloader does `bl 0x08002202` once *0x08001800 == 0x19780217.
 * Stock calls the ARM C-lib __main (scatterload -> __rt_entry -> main). We call
 * our GCC-native equivalent in startup.c, which does the same job. */
    .global image_entry
    .type   image_entry, %function
image_entry:
    push    {r4, lr}
    bl      _start_c
    pop     {r4, pc}
    .size   image_entry, . - image_entry

    .org    0x20a, 0x00
_image_preamble_end:

/* ==========================================================================
 * Default handlers. These live in .text, NOT in the fixed preamble, so they
 * may be placed anywhere. Each reproduces the stock behaviour.
 * ========================================================================*/
    .section .text.default_handlers, "ax", %progbits
    .align  1

    .macro  TRAP_HANDLER name, code
    .weak   \name
    .type   \name, %function
\name:
    movs    r0, #\code
    b       fatal_error_reset
    .size   \name, . - \name
    .endm

    .macro  EMPTY_HANDLER name
    .weak   \name
    .type   \name, %function
\name:
    bx      lr
    .size   \name, . - \name
    .endm

    TRAP_HANDLER  NMI_Handler, 100
    TRAP_HANDLER  HardFault_Handler, 101
    TRAP_HANDLER  MemManage_Handler, 102
    TRAP_HANDLER  BusFault_Handler, 103
    TRAP_HANDLER  UsageFault_Handler, 104
    TRAP_HANDLER  Slot5_Unused_Handler, 110
    TRAP_HANDLER  DebugMon_Handler, 111
    TRAP_HANDLER  Slot7_Unused_Handler, 112
    TRAP_HANDLER  Slot8_Unused_Handler, 113
    TRAP_HANDLER  WWDG_IRQHandler, 114
    TRAP_HANDLER  PVD_IRQHandler, 115
    TRAP_HANDLER  TAMPER_IRQHandler, 116
    TRAP_HANDLER  RTC_IRQHandler, 117
    TRAP_HANDLER  FLASH_IRQHandler, 118
    TRAP_HANDLER  RCC_IRQHandler, 119
    TRAP_HANDLER  EXTI0_IRQHandler, 120
    TRAP_HANDLER  EXTI1_IRQHandler, 121
    TRAP_HANDLER  EXTI3_IRQHandler, 123
    TRAP_HANDLER  EXTI4_IRQHandler, 124
    TRAP_HANDLER  Slot20_Unused_Handler, 125
    TRAP_HANDLER  Slot21_Unused_Handler, 126
    TRAP_HANDLER  Slot22_Unused_Handler, 127
    TRAP_HANDLER  Slot23_Unused_Handler, 128
    TRAP_HANDLER  Slot24_Unused_Handler, 129
    TRAP_HANDLER  Slot25_Unused_Handler, 130
    TRAP_HANDLER  Slot26_Unused_Handler, 131
    TRAP_HANDLER  ADC_IRQHandler, 132
    EMPTY_HANDLER CAN_TX_IRQHandler
    EMPTY_HANDLER CAN_RX1_IRQHandler
    EMPTY_HANDLER CAN_SCE_IRQHandler
    TRAP_HANDLER  TIM1_BRK_IRQHandler, 134
    TRAP_HANDLER  TIM1_UP_IRQHandler, 135
    TRAP_HANDLER  TIM1_TRG_COM_IRQHandler, 136
    TRAP_HANDLER  TIM1_CC_IRQHandler, 137
    TRAP_HANDLER  TIM3_IRQHandler, 138
    TRAP_HANDLER  TIM4_IRQHandler, 139
    TRAP_HANDLER  I2C1_EV_IRQHandler, 140
    TRAP_HANDLER  I2C1_ER_IRQHandler, 141
    TRAP_HANDLER  I2C2_EV_IRQHandler, 142
    TRAP_HANDLER  I2C2_ER_IRQHandler, 143
    TRAP_HANDLER  SPI1_IRQHandler, 144
    TRAP_HANDLER  SPI2_IRQHandler, 145
    EMPTY_HANDLER USART1_IRQHandler
    EMPTY_HANDLER USART3_IRQHandler
    TRAP_HANDLER  EXTI15_10_IRQHandler, 148
    TRAP_HANDLER  RTCAlarm_IRQHandler, 149
    TRAP_HANDLER  Slot51_Unused_Handler, 150
    TRAP_HANDLER  TIM5_IRQHandler, 151
    TRAP_HANDLER  Slot53_Unused_Handler, 152
    TRAP_HANDLER  UART4_IRQHandler, 153
    TRAP_HANDLER  UART5_IRQHandler, 154
    TRAP_HANDLER  TIM6_IRQHandler, 155
    TRAP_HANDLER  TIM7_IRQHandler, 156
    TRAP_HANDLER  Slot58_Unused_Handler, 164

/* The five slots that carry a real handler in the stock image. Weak defaults so
 * the image links before those subsystems are ported; each is overridden by the
 * C definition of the same name once its subsystem lands.
 *   trap codes here are NOT stock (stock has real code at these slots) -- they
 *   are distinct 2xx values so an unported handler firing is identifiable. */
    TRAP_HANDLER  EXTI2_IRQHandler,      217   /* stock @0x08002edc */
    TRAP_HANDLER  CAN_RX0_IRQHandler,    229   /* stock @0x08002f32 */
    TRAP_HANDLER  EXTI9_5_IRQHandler,    232   /* stock @0x08002f3e */
    TRAP_HANDLER  TIM2_IRQHandler,       237   /* stock @0x08002f72 */
    TRAP_HANDLER  USART2_IRQHandler,     247   /* stock @0x08003016 */

    .end
